use crate::list::*;
#[test]
fn paged_formatted_exact_extent_preserves_full_source_and_four_locale_cells_at_original_64k(){
 use crate::{NativeEncodeControl,paged_text::PagedText};
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../📋️list/🧪️tests/🧫️fixtures/🏷️formatted-exact-extent.json")).unwrap();assert_eq!(fixture["maximumAllocationBytes"],65536);assert_eq!(fixture["maximumItems"],1);assert_eq!(fixture["maximumBytes"],4096);assert_eq!(fixture["payloadBytes"],8194);assert_eq!(fixture["originalWireBytes"],8194);
 let value="x".repeat(8194);let pointer=value.as_ptr();let original=crate::staged_rig::source(value);let mut wire=vec![b' ';8194];wire[0]=b'1';wire[1]=b'7';let wire=crate::staged_rig::source(wire);let mut outputs:[Option<PagedText<{isize::MAX as usize}>>;5]=std::array::from_fn(|_|None);let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);let mut construction=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);
 outputs[0]=Some(crate::staged_rig::encode_success(&wire,&mut control,&mut construction,&mut work,16384,"",""));
 for index in 1..5{let en=fixture["matrix"][index-1]=="En";let(prefix,suffix)=if en{("Set label to ","")}else{("Beschriftung auf "," setzen")};assert_eq!(prefix,fixture[if en{"prefixEn"}else{"prefixDe"}].as_str().unwrap());assert_eq!(suffix,fixture[if en{"suffixEn"}else{"suffixDe"}].as_str().unwrap());outputs[index]=Some(crate::staged_rig::encode_success(&original,&mut control,&mut construction,&mut work,16384,prefix,suffix));}
 let admitted=control.owned_bytes();assert_eq!(original.borrow().get().as_ptr(),pointer);let retained=outputs.iter().map(|value|value.as_ref().unwrap().allocated_bytes()).sum::<usize>();assert_eq!(outputs[0].as_ref().unwrap().borrow().unwrap().byte_len(),8194);
 for(index,owner)in outputs.iter().enumerate().skip(1){let en=fixture["matrix"][index-1]=="En";let expected=fixture[if en{"expectedEnBytes"}else{"expectedDeBytes"}].as_u64().unwrap()as usize;let text=owner.as_ref().unwrap().borrow().unwrap();assert_eq!(text.byte_len(),expected);let(prefix,suffix)=if en{("Set label to ","")}else{("Beschriftung auf "," setzen")};for(at,byte)in prefix.bytes().chain(original.borrow().get().bytes()).chain(suffix.bytes()).enumerate(){assert_eq!(text.byte_at(at),Some(byte));}}
 assert_eq!(retained,admitted);assert!(admitted<=65536);let mut disposed=0;for owner in outputs{disposed+=crate::staged_rig::close_text(owner.unwrap())}assert_eq!(disposed,retained);drop(control);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(construction.into_recipient().is_ok());crate::staged_rig::close_source(wire);crate::staged_rig::close_source(original);
}

#[test]
fn paged_formatted_exact_extent_retains_every_refused_prefix_and_complete_utf8_borrow(){
 use crate::{NativeEncodeControl,RetireOwned,ValueError,ValueRefusalKind,paged_text::{PagedText,PagedTextEncodeFrame,PagedTextReadStep,PagedTextStage,TextReadSource,TextSourceByteReply,TextSourceByteComplete}};
 use std::sync::atomic::{AtomicUsize,Ordering};
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../📋️list/🧪️tests/🧫️fixtures/❌️formatted-exact-extent.json")).unwrap();assert_eq!(fixture["sourceBytes"],8194);assert_eq!(fixture["maximumAllocationBytes"],65536);assert_eq!(fixture["maximumItems"],1);assert_eq!(fixture["maximumBytes"],4096);assert_eq!(fixture["initialAllocationBytes"],4096);assert_eq!(fixture["interiorBytes"],256);let payload=fixture["shortText"].as_str().unwrap().repeat(fixture["longRepeat"].as_u64().unwrap()as usize)+fixture["longSuffix"].as_str().unwrap();assert_eq!(payload.len(),8194);
 struct Probe{body:String,mode:u8,reads:AtomicUsize}
 impl TextReadSource for Probe{
  fn byte_len(&self)->usize{let count=self.reads.load(Ordering::SeqCst);match self.mode{5 if count>=self.body.len()+6=>6,6 if count<6=>6,_=>self.body.len()}}
  fn byte_at(&self,index:usize)->Option<u8>{let count=self.reads.fetch_add(1,Ordering::SeqCst);if self.mode==6&&count<6{"ä🧩".as_bytes().get(index).copied()}else{self.body.as_bytes().get(index).copied()}}
  fn read_recorded(&self,mut reply:TextSourceByteReply<'_,'_>)->TextSourceByteComplete{let _=reply.performed(1).expect("original Work receipt must accept the source report");if self.mode==9{self.reads.fetch_add(1,Ordering::SeqCst);reply.complete(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original formatter refused")),1)}else{let value=self.byte_at(reply.index());reply.complete(Ok(value),1)}}
 }
 impl RetireOwned for Probe{type RetirementCursor=<(String,u8,usize) as RetireOwned>::RetirementCursor;fn retirement_ready(&self)->bool{self.body.retirement_ready()}fn retirement_seed(self)->Self::RetirementCursor{(self.body,self.mode,self.reads.into_inner()).retirement_seed()}fn retirement_birth_bytes(&self)->Option<usize>{self.retirement_ready().then_some(std::mem::size_of::<Self::RetirementCursor>())}fn controlled_retirement_supported()->bool{<(String,u8,usize) as RetireOwned>::controlled_retirement_supported()}}
 for(mode_index,mode)in fixture["modes"].as_array().unwrap().iter().enumerate(){let mode=mode.as_str().unwrap();let source_body=if mode=="duplicate-formatter"{"short".to_owned()}else{payload.clone()};let pointer=source_body.as_ptr();let original=crate::staged_rig::source(Probe{body:source_body,mode:mode_index as u8,reads:AtomicUsize::new(0)});let foreign=if mode=="duplicate-formatter"{Some(crate::staged_rig::source(Probe{body:"other".to_owned(),mode:8,reads:AtomicUsize::new(0)}))}else{None};let mut allow=|_|true;let mut control=NativeEncodeControl::new(if mode=="initial4096"{4096}else{65536},&mut allow);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let mut output:Option<PagedText<{isize::MAX as usize}>>=None;let mut frame=PagedTextEncodeFrame::new(&mut output,if mode=="segment-one-short"{8193}else{16384}).unwrap();let mut stopped=false;let mut did_cancel=false;
  for _ in 0..100000{let stage=frame.stage();let position=frame.phase_progress().0;if mode=="count-cancel"&&stage==PagedTextStage::Validating&&position==0||matches!(mode,"declaration-cancel"|"ignored-declaration-cancel")&&stage==PagedTextStage::Copying&&position==0||mode=="interior-cancel"&&stage==PagedTextStage::Copying&&position==256{frame.begin_close();did_cancel=true;stopped=true;break}
   if mode=="duplicate-formatter"&&stage==PagedTextStage::Copying&&position==5{let g=crate::staged_rig::grant(frame.demand(original.borrow()).unwrap());let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(foreign.as_ref().unwrap().borrow(),control,g)))))).unwrap().unwrap().unwrap();let failure=match turn.result{Err(failure)=>failure,_=>panic!("foreign original source was accepted")};crate::staged_rig::close_encode_failure(failure);stopped=true;break}
   let turn=crate::staged_rig::encode_turn(&mut frame,&original,&mut control,&mut physical,&mut work);match turn.result{Err(failure)=>{crate::staged_rig::close_encode_failure(failure);stopped=true;break},Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},_=>panic!("refused original formatter was published: {mode}")}}
  assert!(stopped,"original formatter never reached its refusal or cancellation: {mode}");assert_eq!(original.borrow().get().body.as_ptr(),pointer);let retained=frame.retained_capacity();assert_eq!(retained,control.owned_bytes());if mode=="interior-cancel"{assert_eq!(frame.retained_len(),256)}if mode=="second-short"{assert_eq!(frame.retained_len(),6)}if mode=="duplicate-formatter"{assert_eq!(frame.retained_len(),5)}if matches!(mode,"count-cancel"|"declaration-cancel"|"ignored-declaration-cancel"|"segment-one-short"|"second-long"|"ignored-formatter-error"){assert_eq!(retained,0)}if mode=="initial4096"{assert_eq!(frame.retained_len(),0);assert!(retained>0&&retained<=4096)}
  if did_cancel&&mode=="ignored-declaration-cancel"||mode=="ignored-formatter-error"{let g=crate::staged_rig::grant(crate::RetirementDemand{depth:1,..Default::default()});let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap().unwrap().unwrap();let failure=match turn.result{Err(failure)=>failure,_=>panic!("ignored cancellation or refusal restarted the producer")};crate::staged_rig::close_encode_failure(failure)}
  assert_eq!(crate::staged_rig::close_encode_frame(&mut frame),retained);drop(frame);assert!(output.is_none());drop(control);assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());if let Some(foreign)=foreign{crate::staged_rig::close_source(foreign)}crate::staged_rig::close_source(original);
 }
 for text in [fixture["shortText"].as_str().unwrap(),payload.as_str()]{let original=crate::staged_rig::source(text.to_owned());let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let(mut paged,mut inline)=crate::staged_rig::encode_inline_success::<_,{isize::MAX as usize}>(&original,&mut control,&mut physical,&mut work,8194,"","");if text.len()<=128{assert!(paged.is_none());let cell=inline.as_mut().unwrap();assert_eq!(cell.borrow().unwrap(),text);assert_eq!(control.owned_bytes(),0);assert!(cell.close_one(1));assert!(cell.borrow().is_err())}else{assert!(inline.is_none());let owner=paged.as_ref().unwrap();assert_eq!(owner.borrow().unwrap().byte_len(),8194);assert!(owner.borrow().unwrap().bytes().eq(original.borrow().get().bytes()));let retained=owner.allocated_bytes();assert_eq!(retained,control.owned_bytes());assert_eq!(crate::staged_rig::close_text(paged.take().unwrap()),retained)}drop(control);assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());crate::staged_rig::close_source(original);
 }
}


/// 🧾️ A real construction reply survives unwind in the original paged owner before physical allocation.
#[test]
fn paged_text_page_allocation_recovers_the_recorded_original_reply(){
 use crate::{NativeEncodeControl,ErasedSnapshotRetirement,paged_text::PagedText,retained_clone::{RetainedCloneGrant,RetainedCloneProgress}};
 struct Work;impl crate::OriginalWorkRecipient for Work{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),crate::ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(context))}
 fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(context))}
 fn admits<'a,'turn,'source>(&mut self,_:&mut (),q:crate::OriginalWorkQuote<'a>,_:u64,_:u64)->crate::OriginalWorkQuoteComplete<'a>where 'source:'turn{q.complete(Ok(true))}}
 struct Physical{interrupt:bool,receipts:usize,submitted:RetainedCloneProgress}impl crate::OriginalConstructionRecipient for Physical{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),crate::ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}fn grant<'a,'turn,'source>(&mut self,_:&mut (),q:crate::OriginalConstructionGrant<'a>)->crate::OriginalConstructionGrantComplete<'a>where 'source:'turn{let d=q.demand();let completed=q.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}));if self.interrupt{self.interrupt=false;std::hint::black_box(&completed);panic!("original text grant interrupted after reply")}completed}fn accept<'a,'turn,'source>(&mut self,_:&mut (),receipt:crate::OriginalConstructionAccept<'a>)->crate::OriginalConstructionAcceptComplete<'a>where 'source:'turn{self.receipts+=1;let result=self.submitted.checked_add(receipt.progress()).map(|sum|self.submitted=sum);receipt.complete(result)}fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{self.submitted}}
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../📋️list/🧪️tests/🧫️fixtures/🏷️formatted-exact-extent.json")).unwrap();let limit=fixture["payloadBytes"].as_u64().unwrap()as usize;let mut text=PagedText::<{isize::MAX as usize}>::empty();let demand=text.next_encoded_page_demand(Some(limit)).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let mut physical=crate::OriginalConstructionAuthority::new(Physical{interrupt:true,receipts:0,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(Work);let mut callback=|_|true;let mut control=NativeEncodeControl::new(65536,&mut callback);
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,crate::ValueError>(text.reserve_encoded_page(control,grant,Some(limit)))))).unwrap())));assert!(interrupted.is_err());assert_eq!(text.allocated_bytes(),0);assert_eq!(text.next_encoded_page_demand(Some(limit)).unwrap(),demand);
 let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,crate::ValueError>(text.reserve_encoded_page(control,grant,Some(limit)))))).unwrap()).unwrap().unwrap();let receipt=match turn.result{Ok(Some(receipt))=>receipt,_=>panic!("original page reservation did not complete")};assert_eq!(receipt.retained_capacity_bytes,text.allocated_bytes());assert_eq!(control.owned_bytes(),receipt.retained_capacity_bytes);assert_eq!(serde_json::to_value(receipt.retained_capacity_bytes).unwrap(),serde_json::json!(demand.capacity_bytes));assert_eq!(physical.inspect(|producer|producer.receipts),1);
 while !text.terminal_is_empty(){let d=text.next_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let units=text.next_computational_work(4096).unwrap();let mut actual=None;let turn=crate::eff::settled(crate::eff::with_effect(g,units,&mut actual,|effect|text.close_step(effect)));assert!(turn.result.is_ok());}assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());
}
